import sys
M = 1000000007
P = 2 * (M + 1)
def fib(n):
    a, b = 0, 1
    for c in bin(n)[2:]:
        t = a * (2 * b - a) % M
        u = (a * a + b * b) % M
        if c == '1':
            a, b = u, (t + u) % M
        else:
            a, b = t, u
    return a
def main():
    toks = sys.stdin.buffer.read().split()
    memo = {}
    out = []
    for tk in toks:
        r = memo.get(tk)
        if r is None:
            r = memo[tk] = fib(int(tk) % P)
        out.append(r)
    sys.stdout.write("\n".join(map(str, out)) + "\n")
main()
